import type { Command } from '@endora-commerce/platform/commands';
// D-178 — the co-transactional seam this module consumes; why it is imported
// from `organizations`' `ports` subpath is on the interface.
import type { PersonalOrganizationProvisionApi } from '@endora-commerce/mod-organizations/ports';
import { CustomerAccount } from '../entities/customer-account.entity.js';
import { accountCreatedAuditState } from '../services/customer-account-audit-state.js';

export interface RegisterSocialInput {
  /** Generated by the caller: the personal organisation records it as its account link. */
  readonly customerAccountId: string;
  /** Folded already. */
  readonly email: string;
  /** A random one: no password was ever chosen for this account (issue #222). */
  readonly passwordHash: string;
  /** The store the federated sign-in was started on (feature 154, owner decision D6). */
  readonly salesChannelId: string;
  readonly preferredLanguage: string | null;
}

/**
 * `customer_account.register_social` — an account created by a federated
 * sign-in, **and** its personal Organization, in one transaction (D-178).
 *
 * `specs/193-admin-form-extensions/` D-300.10, D-300.31: it was a hand-audited
 * `em.transactional` in the `mfa` seam, and a root Command started there would
 * have opened a transaction of its own. As a Command it runs the provisioning
 * (`organization.personal.provision`) as its child through `run`, on its one
 * transaction, and records the entry the seam wrote by hand — the same action,
 * object and state. It is a buyer's own write under the anonymous system
 * actor, so it declares `buyerSelfService` (listed in the manifest's
 * `buyerSelfServiceActions`) and its child inherits it.
 *
 * The provider sends no name with the claim the seam reads, so the
 * organisation is named from the address' local part — what
 * `PersonalOrganizationService.personalName` falls back to.
 */
export function makeRegisterSocialCommand(
  deps: { readonly personalOrganizations: PersonalOrganizationProvisionApi },
  input: RegisterSocialInput,
): Command<{ id: string; organizationId: string | null }> {
  return {
    action: 'customer_account.register_social',
    objectType: 'customer_account',
    objectId: input.customerAccountId,
    buyerSelfService: true,
    run: async ({ em, run }) => {
      if (!run) throw new Error('customer_account.register_social runs its personal organisation as a child Command; run it on the bus.');
      const organization = await deps.personalOrganizations.provisionFor(
        { em, run },
        { customerAccountId: input.customerAccountId, email: input.email, salesChannelId: input.salesChannelId },
      );
      const account = em.create(CustomerAccount, {
        id: input.customerAccountId,
        email: input.email,
        passwordHash: input.passwordHash,
        // Issue #222 — no password was chosen, so none is on record.
        passwordSetAt: null,
        firstName: '',
        lastName: '',
        organizationId: organization.id,
        // The individual administers their personal Organization (owner ruling
        // PR-3, research R-34) — the provisioning answer's id, because the role
        // row exists only in this transaction.
        organizationRoleId: organization.administratorRoleId,
        emailVerifiedAt: new Date(),
        // Issue #652 (D-292) — the language of the page the sign-in started on.
        preferredLanguage: input.preferredLanguage,
      });
      await em.persist(account).flush();
      return {
        result: { id: account.id, organizationId: organization.id },
        before: null,
        after: accountCreatedAuditState(account),
      };
    },
  };
}
